//! Explicit xy Bradford adaptation, not inferred white balance.
use crate::effects::{p,Params,Frame};
pub fn apply(pr:&Params,f:&mut Frame,t:f64)->Result<(),String>{super::frame::validate(f)?;let get=|k,d|p(pr,k,d,t) as f64;let g=get("gamut",0.);if g.fract()!=0.||!(0. ..=7.).contains(&g){return Err("adaptation gamut0..7".into())}let from=[get("source_x",0.3127),get("source_y",0.329)];let to=[get("target_x",0.3127),get("target_y",0.329)];let amount=get("amount",1.);if !(0. ..=1.).contains(&amount){return Err("adaptation amount0..1".into())}let m=super::managed::white_adaptation(g as usize,from,to)?;for(i,p) in f.d.chunks_exact_mut(4).enumerate(){if i%65536==0{crate::guard::check()}let old=[p[0] as f64,p[1] as f64,p[2] as f64];let c=super::managed::mv(m,old);for j in 0..3{let v=old[j]+amount*(c[j]-old[j]);if !v.is_finite()||v.abs()>f32::MAX as f64{return Err("adaptation overflow".into())}p[j]=v as f32}}Ok(())}
pub fn catalog()->Vec<super::Entry>{vec![("white_adaptation","Explicit Bradford source-white xy -> target-white xy in declared linear RGB gamut. Signed/HDR samples preserved, no clipping/encoding. Illuminant is caller declared, not inferred from image. Partial amount is matrix blend, not spectral illuminant interpolation.",&[("gamut",0.,"linear gamut0..7"),("source_x",0.3127,"sourcewhite CIE x"),("source_y",0.329,"sourcewhite CIE y"),("target_x",0.3127,"targetwhite CIE x"),("target_y",0.329,"targetwhite CIE y"),("amount",1.,"0..1")])]}
